import { editProjectKpiConfig } from '~/client';
import type { EditProjectKpiConfigResponse, KpiRulesConfig } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useEditProjectKpiRules = defineMutation(() => {
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (params: { data: KpiRulesConfig; projectId: string }): Promise<EditProjectKpiConfigResponse> =>
      editProjectKpiConfig({
        composable: '$fetch',
        path: { project_id: params.projectId },
        body: ref(params.data),
      }),
    onSuccess: (_, params) => {
      const queryCache = useQueryCache();
      queryCache.invalidateQueries({ key: ['project-edit-tabs-status', params.projectId] });
      queryCache.setQueryData(['project.edit.kpi-rules', params.projectId], () => {
        return params.data;
      });
      showToastSuccess(`Project KPI rules edited successfully`);
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    editProjectKpiConfig: mutateAsync,
    isEditProjectGeneralInfoLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
