import type { ConversationalKpiRulesConfig, NonConversationalKpiConfig } from '~/client';

export interface KPIs extends ConversationalKpiRulesConfig, NonConversationalKpiConfig {}

export interface KpiDefinition {
  description: string;
  label: string;
  toggleId: string;
  group: 'conversational' | 'non_conversational';
  kpiId?: keyof KPIs;
}

