export const CONVERSATIONAL_KPIS: (keyof KPIs)[] = (Object.keys(canvassingProjectKpi) as (keyof KPIs)[]).filter(
  (key) => canvassingProjectKpi[key].group === 'conversational'
);

export const NON_CONVERSATIONAL_KPIS: (keyof KPIs)[] = (Object.keys(canvassingProjectKpi) as (keyof KPIs)[]).filter(
  (key) => canvassingProjectKpi[key].group === 'non_conversational'
);
