<template>
  <AppLoader v-if="isLoading" subject="KPI configuration" />
  <AppError v-else-if="error" :error="error" title="Failed to load KPI configuration" />
  <AppEmpty v-else-if="!data" subject="KPI configuration" />
  <form v-else class="grid grid-cols-8 gap-6" @submit="onSubmit" @vue:mounted="onFormMounted">
    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Conversational KPI Charts</CardTitle>
      </CardHeader>
      <CardContent class="grid grid-cols-1 md:grid-cols-2 gap-6">
        <KpiItemWrapper
          v-for="key in CONVERSATIONAL_KPIS"
          :key="key"
          :toggle-id="canvassingProjectKpi[key].toggleId"
          :label="canvassingProjectKpi[key].label"
          :kpi-id="canvassingProjectKpi[key].kpiId"
        />
      </CardContent>
    </Card>
    <Card class="col-span-8">
      <CardHeader>
        <CardTitle>Non-Conversational KPI Charts</CardTitle>
      </CardHeader>
      <CardContent class="grid grid-cols-1 md:grid-cols-2 gap-6">
        <KpiItemWrapper
          v-for="key in NON_CONVERSATIONAL_KPIS"
          :key="key"
          :toggle-id="canvassingProjectKpi[key].toggleId"
          :label="canvassingProjectKpi[key].label"
          :kpi-id="canvassingProjectKpi[key].kpiId"
        />
      </CardContent>
    </Card>
    <Card class="col-span-8">
      <CardContent class="flex justify-end w-full">
        <Button
          type="submit"
          :disabled="isEditProjectGeneralInfoLoading || isEqual(data, processedDataFromForm)"
          :loading="isEditProjectGeneralInfoLoading"
          >Save</Button
        >
      </CardContent>
    </Card>
    <NavigationGuard
      v-if="data"
      :saved-data="data"
      :changed-data="processedDataFromForm"
      title="Warning"
      description="You have some unsaved changes on this tab! Save them before switching to another tab."
      confirm-text="Discard Changes"
    />
  </form>
</template>

<script setup lang="ts">
import { useForm } from 'vee-validate';
import { formSchema } from '~/constants/validationSchemas/projectEditKPICanvassing';
import { getKpiConfigForProject } from '~/client';
import type { KpiRulesConfig } from '~/client';
import { useEditProjectKpiRules } from '~/mutations/project/edit/kpi';
import { isEqual } from 'lodash';
import {
  canvassingProjectKpi,
  CONVERSATIONAL_KPIS,
  NON_CONVERSATIONAL_KPIS,
} from '~/constants/projects/canvassingProjectKpi';

definePageMeta({
  backGroup: 'project-edit',
  roles: ['admin'],
  backLabel: 'project edit',
});

const route = useRoute('projects-id-edit-kpi-rules');

const { data, isLoading, error } = useQuery({
  key: () => ['project.edit.kpi-rules', route.params.id],
  query: () => getKpiConfigForProject({ composable: '$fetch', path: { project_id: route.params.id } }),
  enabled: () => !!route.params.id,
});

const { handleSubmit, setValues, values } = useForm({
  validationSchema: formSchema,
  initialValues: {},
});

const { editProjectKpiConfig, isEditProjectGeneralInfoLoading } = useEditProjectKpiRules();

const onSubmit = handleSubmit(async () => {
  if (!processedDataFromForm.value) return;

  await editProjectKpiConfig({ data: processedDataFromForm.value, projectId: route.params.id });
});

function onFormMounted() {
  if (!data.value) return;

  const formValues: Record<string, boolean> = {
    conversation_metrics_evaluation_enabled: data.value.conversational_config.conversation_metrics_evaluation_enabled,
    mobile_permission_checking: data.value.non_conversational_config.mobile_permission_checking.enabled,
    conversation_duration_checking_enabled: data.value.conversational_config.conversation_duration_checking.enabled,
    work_shift_time_range_checking_enabled: data.value.non_conversational_config.work_shift_time_range_checking.enabled,
    time_near_the_door_checking_enabled: data.value.non_conversational_config.time_near_the_door_checking.enabled,
    survey_rate_checking_enabled: data.value.non_conversational_config.survey_rate_checking.enabled,
    response_enter_distance_checking_enabled:
      data.value.non_conversational_config.response_enter_distance_checking.enabled,
    mobile_battery_checking_enabled: data.value.non_conversational_config.mobile_battery_checking.enabled,
  };

  setValues(formValues, false);
}

const processedDataFromForm = computed<KpiRulesConfig | null>(() => {
  if (!data.value) return null;

  return {
    conversational_config: {
      conversation_metrics_evaluation_enabled: values.conversation_metrics_evaluation_enabled || false,
      conversation_duration_checking: {
        enabled: values.conversation_duration_checking_enabled || false,
        value: data.value.conversational_config.conversation_duration_checking.value,
      },
    },
    non_conversational_config: {
      mobile_permission_checking: {
        enabled: values.mobile_permission_checking || false,
        value: data.value.non_conversational_config.mobile_permission_checking.value,
      },
      mobile_battery_checking: {
        enabled: values.mobile_battery_checking_enabled || false,
        value: data.value.non_conversational_config.mobile_battery_checking.value,
      },
      response_enter_distance_checking: {
        enabled: values.response_enter_distance_checking_enabled || false,
        value: data.value.non_conversational_config.response_enter_distance_checking.value,
      },
      survey_rate_checking: {
        enabled: values.survey_rate_checking_enabled || false,
        value: data.value.non_conversational_config.survey_rate_checking.value,
      },
      time_near_the_door_checking: {
        enabled: values.time_near_the_door_checking_enabled || false,
        value: data.value.non_conversational_config.time_near_the_door_checking.value,
      },
      work_shift_time_range_checking: {
        enabled: values.work_shift_time_range_checking_enabled || false,
        value: data.value.non_conversational_config.work_shift_time_range_checking.value,
      },
    },
  };
});
</script>
