<template>
  <div class="flex flex-col gap-2">
    <div class="flex flex-wrap gap-2 items-center">
      <FormItemWrapper :name="toggleId">
        <template #default="{ slots }">
          <div class="flex flex-row gap-2 flex-wrap w-full">
            <Switch
              :id="toggleId"
              :model-value="slots.componentField.modelValue"
              @update:model-value="slots.field.onChange"
            />

            <div class="flex gap-2 items-center">
              <Label v-if="label" :for="labelFor || toggleId" class="flex flex-row text-nowrap cursor-pointer">
                <span>{{ label }}</span>
              </Label>
              <Popover v-if="popoverDescription">
                <PopoverTrigger><CircleQuestionMarkIcon class="w-5 h-5" /></PopoverTrigger>
                <PopoverContent side="top" class="text-wrap max-w-72 w-fit p-4 z-40">
                  <p class="font-semibold mb-4">{{ label }}</p>
                  {{ popoverDescription }}
                </PopoverContent>
              </Popover>
            </div>
          </div>
        </template>
      </FormItemWrapper>
    </div>
    <slot />
  </div>
</template>

<script setup lang="ts">
import { CircleQuestionMarkIcon } from 'lucide-vue-next';
import { canvassingProjectKpi, type KPIs } from '~/constants/projects/canvassingProjectKpi';

interface Props {
  toggleId: string;
  label: string;
  labelFor?: string;
  kpiId?: keyof KPIs;
  description?: string;
}

const props = defineProps<Props>();

const popoverDescription = computed(() => {
  if (props.description) return props.description;
  if (props.kpiId) return canvassingProjectKpi[props.kpiId].description;
  return undefined;
});
</script>
